@startuml
class Animal {
  +identifier : long
  +name : string
  +breed : string
}

class Owner {
  +identifier : long
  +name : string
  +address : string
  +phone_number : string
}

class Breed {
  +name : string
}

class Physician {
  +identifier : long
  +name : string
  +address : string
  +phone_number : string
}

class Appointment {
  +date : date
  +time : time
}

class MedicalCondition {
  +common_name : string
  +scientific_name : string
}

"0..1" -- "*" Animal : owns
Animal "*" -- "1" Breed : is of
"1" -- "*" Appointment : is attended by
"1" -- "*" Appointment : is attended by
"1" -- "*" Appointment : is responsible for
"1" -- "*" Appointment : is attended by
"1" -- "*" Appointment : is attended by
"*" -- "*" MedicalCondition : detected in
"1" -- "*" MedicalCondition : common for
@enduml

